@Composable fun ProviderProfileScreen(repository:SupabaseProviderRepository,onBack:()->Unit,onUploadedData:()->Unit,onManageBusiness:()->Unit,onEarnings:()->Unit,onPayoutDetails:()->Unit,onSignOut:()->Unit){
 var profile by remember{mutableStateOf<JSONObject?>(null)};var commission by remember{mutableStateOf<JSONObject?>(null)};var error by remember{mutableStateOf<String?>(null)};var policy by remember{mutableStateOf<PolicyContent?>(null)};var confirmSignOut by remember{mutableStateOf(false)};var showAgreement by remember{mutableStateOf(false)}
